#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2012,SC2181
# download-artifacts.sh — Download the built Mule application JAR from the Maven repository (resolving SNAPSHOT timestamps).
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/steps/download-mule-artifacts.yml
#   step   : "Download Artifact from Azure Artifacts" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Inputs (environment):
#   MDF_ARTIFACT_ID   <- ${{ parameters.artifactId }}  [required]
#   MDF_CLASSIFIER    <- ${{ parameters.classifier }}  [default: mule-application]
#   MDF_GROUP_ID      <- ${{ parameters.groupId }}  [required]
#   MDF_SETTINGS_XML  <- $(settingsXml.secureFilePath)  [default: (empty)]
#   MDF_VERSION       <- ${{ parameters.version }}  [required]
# Outputs: resolvedVersion (output), artifactsDir (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_CLASSIFIER=mule-application}"
: "${MDF_GROUP_ID?MDF_GROUP_ID is required (Azure parameter groupId)}"
: "${MDF_SETTINGS_XML=}"
: "${MDF_VERSION?MDF_VERSION is required (Azure parameter version)}"

# >>> extracted body
GROUP_ID="${MDF_GROUP_ID}"
ARTIFACT_ID="${MDF_ARTIFACT_ID}"
VERSION="${MDF_VERSION}"
CLASSIFIER="${MDF_CLASSIFIER}"
SETTINGS_PATH="${MDF_SETTINGS_XML}"
M2_REPO="$(ci_pipeline_workspace)/.m2/repository"
ARTIFACTS_DIR="$(ci_pipeline_workspace)/mule-artifacts"

echo "[DEBUG] ============================================"
echo "[DEBUG] DOWNLOAD MULE ARTIFACTS"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   groupId=$GROUP_ID"
echo "[DEBUG]   artifactId=$ARTIFACT_ID"
echo "[DEBUG]   version=$VERSION"
echo "[DEBUG]   classifier=$CLASSIFIER"
echo "[DEBUG]   settingsPath=$SETTINGS_PATH"
echo "[DEBUG]   m2Repo=$M2_REPO"
echo "[DEBUG]   artifactsDir=$ARTIFACTS_DIR"
echo "[DEBUG] ============================================"

mkdir -p "$ARTIFACTS_DIR"

echo "Downloading: ${GROUP_ID}:${ARTIFACT_ID}:${VERSION}:jar:${CLASSIFIER}"

# Download the artifact
echo "[DEBUG] Running: mvn dependency:get -DgroupId=$GROUP_ID -DartifactId=$ARTIFACT_ID -Dversion=$VERSION -Dclassifier=$CLASSIFIER"
mvn dependency:get \
  -s "$SETTINGS_PATH" \
  -Dmaven.repo.local="$M2_REPO" \
  -DgroupId="$GROUP_ID" \
  -DartifactId="$ARTIFACT_ID" \
  -Dversion="$VERSION" \
  -Dclassifier="$CLASSIFIER" \
  -Dpackaging=jar \
  -Dtransitive=false

if [ $? -ne 0 ]; then
  echo "[DEBUG] mvn dependency:get FAILED"
  ci_log_error "Failed to download artifact."
  exit 1
fi
echo "[DEBUG] mvn dependency:get succeeded"

# Resolve actual version for SNAPSHOTs
RESOLVED_VERSION="$VERSION"
GROUP_PATH=$(echo "$GROUP_ID" | tr '.' '/')
ARTIFACT_DIR="$M2_REPO/$GROUP_PATH/$ARTIFACT_ID/$VERSION"
echo "[DEBUG] Artifact directory: $ARTIFACT_DIR"
echo "[DEBUG] Artifact directory contents: $(ls -la "$ARTIFACT_DIR" 2>&1 | head -15)"

if [[ "$VERSION" == *"SNAPSHOT"* ]]; then
  echo "[DEBUG] SNAPSHOT version — resolving actual JAR filename"
  # Find the actual resolved JAR filename
  RESOLVED_JAR=$(find "$ARTIFACT_DIR" -name "*-${CLASSIFIER}.jar" ! -name "*SNAPSHOT*" 2>/dev/null | head -1)
  if [[ -n "$RESOLVED_JAR" ]]; then
    RESOLVED_VERSION=$(basename "$RESOLVED_JAR" | sed "s/${ARTIFACT_ID}-//" | sed "s/-${CLASSIFIER}.jar//")
    echo "[DEBUG] Resolved SNAPSHOT to: $RESOLVED_VERSION (from $RESOLVED_JAR)"
  else
    echo "[DEBUG] No non-SNAPSHOT JAR found, keeping RESOLVED_VERSION=$RESOLVED_VERSION"
  fi
fi

# Copy artifact to staging directory
JAR_FILE=$(find "$ARTIFACT_DIR" -name "*-${CLASSIFIER}.jar" | head -1)
if [[ -z "$JAR_FILE" ]]; then
  echo "[DEBUG] No JAR matching *-${CLASSIFIER}.jar found in $ARTIFACT_DIR"
  echo "[DEBUG] All files in dir: $(find "$ARTIFACT_DIR" -type f)"
  ci_log_error "JAR file not found in: $ARTIFACT_DIR"
  exit 1
fi
echo "[DEBUG] Source JAR: $JAR_FILE"

cp "$JAR_FILE" "$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar"
echo "[DEBUG] Copied to: $ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar"
echo "[DEBUG] Final JAR size: $(stat -f%z "$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar" 2>/dev/null || stat --printf="%s" "$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar" 2>/dev/null) bytes"

echo "Artifact downloaded to: $ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar"
echo "Resolved version: $RESOLVED_VERSION"

ci_set_var resolvedVersion "$RESOLVED_VERSION"
ci_set_var artifactsDir "$ARTIFACTS_DIR"
echo "[DEBUG] Outputs: resolvedVersion=$RESOLVED_VERSION, artifactsDir=$ARTIFACTS_DIR"
echo "[DEBUG] DOWNLOAD MULE ARTIFACTS COMPLETE"
# <<< extracted body
